// (同じ要求を繰り返す。ADR-0209 §5.2)。
type DeletionStatus string

// Error エラーの本文。HTTP ステータスは `code` から決まる(ErrorCode の対応表)。
// `message` は日本語の説明で、Go の内部情報(スタック・型名)を含めない。
type Error struct {
	// Code 安定したエラーコード。WASM 境界(engine/wasmapi の Code* 定数。ADR-0011 §5・§13)と語彙を共通にし、
	// **同じ失敗は HTTP と WASM で同じ code** になる(ADR-0200)。
	//
	// WASM 境界と共通:
	// | code | 意味 | HTTP |
	// |---|---|---|
	// | invalid_json | JSON として壊れている / 型が合わない(整数のフィールドに小数を含む) | 400 |
	// | unknown_field | 契約にないフィールド | 400 |
	// | invalid_enum | 列挙(形式・タイプ・天候・フィールド・状態異常)の値が未知 | 400 |
	// | invalid_input | 入力検証(SP の範囲・合計、ランク、レベル、性格が HP など)。候補・観測の件数上限(`maxItems`)超過、持ち物候補の重複(`uniqueItems`)、`maxCandidates` の範囲外を含む(ADR-0208)。calc-svc では `sp` と StatBlock の6キー(null 値を含む)の欠落も含む(ADR-0200 §4)。`getMovesByIds` の `ids` の件数超過・欠落も含む。調整(`/api/calc/adjust/*`)の発数・しきい値・補正・上限(ceiling)の範囲外、変化技での探索、下限が上限を超える配分(ADR-0250)も含む。team では構築名の長さ・メンバー数・技の重複・SP の範囲と合計・1端末が持てる構築の上限(ADR-0213 §2)も含む | 400 |
	// | unknown_preset | 未知の防御側プリセット | 400 |
	// | duplicate_preset | 防御側プリセットの重複 | 400 |
	// | invalid_preset | 防御側プリセットの定義が不正 | 400 |
	// | invalid_reverse_side | 逆算の side が defender / attacker のどちらでもない | 400 |
	// | no_observation | 観測が1件も無い | 400 |
	// | invalid_observation | 観測の指定が不正(percent / percentTenths / damage のちょうど1つでない・範囲外) | 400 |
	// | type_chart_missing | タイプ相性表が無い(HTTP では常にマスタ = 起動時に読み込んだ Store 側の不備で、クライアントの入力起因では起こらない) | 500 |
	// | invalid_type_chart | タイプ相性表の定義が不正(同上。HTTP では常にマスタ側の不備) | 500 |
	// | unknown_type | 相性表に無いタイプ | 400 |
	// | internal | 上記以外の失敗(回復した panic を含む) | 500 |
	//
	// HTTP だけのもの:
	// | code | 意味 | HTTP |
	// |---|---|---|
	// | missing_header | X-Device-Id / X-Session-Id が無い・空 | 400 |
	// | invalid_header | X-Device-Id / X-Session-Id が UUID でない・同名ヘッダの重複(UUID 形式の検証は gateway だけが行う。ADR-0202) | 400 |
	// | unknown_species | speciesKey がマスタに無い | 400 |
	// | unknown_move | moveId がマスタに無い | 400 |
	// | unknown_item | itemId がマスタに無い | 400 |
	// | unknown_ability | abilityId がマスタに無い | 400 |
	// | unknown_nature | natureId がマスタに無い | 400 |
	// | not_found | ルートが無い / このサービスの担当外の操作 / この端末が持っていないリソース ID(他端末のものか実在しないかを区別しない。403 にしない。ADR-0209 §6-2) | 404 |
	// | master_unavailable | マスタ(pokedex の MySQL)を参照できない | 503 |
	// | store_unavailable | 保存データの DB(record / team の TiDB)を参照できない。`master_unavailable` と分けるのは原因も復旧手順も別で、「計算はできるが保存はできない」状態(CLAUDE.md 絶対ルール5)をクライアントが区別できる必要があるため(ADR-0209 §5.3) | 503 |
	// | upstream_unavailable | gateway から下流のサービスに届かない(接続できない・タイムアウト・上流が未設定。ADR-0202)。calc・pokedex は自サービスの過負荷・締め切り超過でも返す(ADR-0801) | 503 |
	Code    ErrorCode `json:"code"`
	Message string    `json:"message"`
}

// ErrorCode 安定したエラーコード。WASM 境界(engine/wasmapi の Code* 定数。ADR-0011 §5・§13)と語彙を共通にし、
// **同じ失敗は HTTP と WASM で同じ code** になる(ADR-0200)。
//
// WASM 境界と共通:
// | code | 意味 | HTTP |
// |---|---|---|
// | invalid_json | JSON として壊れている / 型が合わない(整数のフィールドに小数を含む) | 400 |
// | unknown_field | 契約にないフィールド | 400 |
// | invalid_enum | 列挙(形式・タイプ・天候・フィールド・状態異常)の値が未知 | 400 |
// | invalid_input | 入力検証(SP の範囲・合計、ランク、レベル、性格が HP など)。候補・観測の件数上限(`maxItems`)超過、持ち物候補の重複(`uniqueItems`)、`maxCandidates` の範囲外を含む(ADR-0208)。calc-svc では `sp` と StatBlock の6キー(null 値を含む)の欠落も含む(ADR-0200 §4)。`getMovesByIds` の `ids` の件数超過・欠落も含む。調整(`/api/calc/adjust/*`)の発数・しきい値・補正・上限(ceiling)の範囲外、変化技での探索、下限が上限を超える配分(ADR-0250)も含む。team では構築名の長さ・メンバー数・技の重複・SP の範囲と合計・1端末が持てる構築の上限(ADR-0213 §2)も含む | 400 |
// | unknown_preset | 未知の防御側プリセット | 400 |
// | duplicate_preset | 防御側プリセットの重複 | 400 |
// | invalid_preset | 防御側プリセットの定義が不正 | 400 |
// | invalid_reverse_side | 逆算の side が defender / attacker のどちらでもない | 400 |
// | no_observation | 観測が1件も無い | 400 |
// | invalid_observation | 観測の指定が不正(percent / percentTenths / damage のちょうど1つでない・範囲外) | 400 |
// | type_chart_missing | タイプ相性表が無い(HTTP では常にマスタ = 起動時に読み込んだ Store 側の不備で、クライアントの入力起因では起こらない) | 500 |
// | invalid_type_chart | タイプ相性表の定義が不正(同上。HTTP では常にマスタ側の不備) | 500 |
// | unknown_type | 相性表に無いタイプ | 400 |
// | internal | 上記以外の失敗(回復した panic を含む) | 500 |
//
// HTTP だけのもの:
// | code | 意味 | HTTP |
// |---|---|---|
// | missing_header | X-Device-Id / X-Session-Id が無い・空 | 400 |
// | invalid_header | X-Device-Id / X-Session-Id が UUID でない・同名ヘッダの重複(UUID 形式の検証は gateway だけが行う。ADR-0202) | 400 |
// | unknown_species | speciesKey がマスタに無い | 400 |
// | unknown_move | moveId がマスタに無い | 400 |
// | unknown_item | itemId がマスタに無い | 400 |
// | unknown_ability | abilityId がマスタに無い | 400 |
// | unknown_nature | natureId がマスタに無い | 400 |
// | not_found | ルートが無い / このサービスの担当外の操作 / この端末が持っていないリソース ID(他端末のものか実在しないかを区別しない。403 にしない。ADR-0209 §6-2) | 404 |
// | master_unavailable | マスタ(pokedex の MySQL)を参照できない | 503 |
// | store_unavailable | 保存データの DB(record / team の TiDB)を参照できない。`master_unavailable` と分けるのは原因も復旧手順も別で、「計算はできるが保存はできない」状態(CLAUDE.md 絶対ルール5)をクライアントが区別できる必要があるため(ADR-0209 §5.3) | 503 |
// | upstream_unavailable | gateway から下流のサービスに届かない(接続できない・タイムアウト・上流が未設定。ADR-0202)。calc・pokedex は自サービスの過負荷・締め切り超過でも返す(ADR-0801) | 503 |
type ErrorCode string

// FieldState defines model for FieldState.
type FieldState struct {
	AttackerScreens *Screens `json:"attackerScreens,omitempty"`
	DefenderScreens *Screens `json:"defenderScreens,omitempty"`
	Terrain         *Terrain `json:"terrain,omitempty"`
	Weather         *Weather `json:"weather,omitempty"`
}

// Format 対戦形式。計算(/api/calc・/api/calc/bulk・/api/calc/reverse)では double のとき次を掛ける(issue 232 案B のダブル分・ADR-0222)。
//   - 防御側の壁(リフレクター・ひかりのかべ・オーロラベール): ×2732/4096(single は ×1/2)。急所は壁を無視する
//   - 全体技(技の対象が相手全体・自分以外全体): 基礎ダメージに ×3072/4096(天候・急所より前)。
//     1対1の計算なので、全体技は常に2体以上に当たる前提で掛ける。味方の効果(てだすけ等)は扱わない
//
// 技の対象をマスタが持たない間(issue 288)は、double の攻撃技に UnsupportedMark
// (target=move・reason=move_target_unknown)を付け、全体技の補正は掛けない(壁は掛ける)。
type Format string

// FrequentOpponent 「よく使う相手」1件(ADR-0209 §3 #2)。端末内の計算イベントの集計で、他端末のイベントは混ざらない。
// 個体の中身(技・持ち物・特性・性格・SP)・ダメージの数値は返さない(集計に使うのは防御側の種族だけ)。
type FrequentOpponent struct {
	// Count 減衰をかける前の、集計対象として残っている計算イベントの件数
	Count int `json:"count"`

	// LastCalculatedAt この相手を最後に計算した時刻(イベントの `occurred_at`)
	LastCalculatedAt time.Time `json:"lastCalculatedAt"`

	// Score 頻度 × 時間減衰。並び順のための相対値で、絶対値に意味は無い(ADR-0209 §4)
	Score float64 `json:"score"`

	// SpeciesKey 防御側(相手)の種族。名前・タイプは pokedex-svc から引く
	SpeciesKey SpeciesKey `json:"speciesKey"`
}

// HPLineKind HP 実数値が属するライン(16n = HP mod 16 が 0、16n-1 = 15、none = どちらでもない)
type HPLineKind string

// HPLinePoint defines model for HPLinePoint.
type HPLinePoint struct {
	// Hp そのラインの HP 実数値
	Hp int `json:"hp"`

	// Sp その HP にする HP の SP
	Sp int `json:"sp"`

	// SpDelta 現在の SP からの差(次のラインは正、前のラインは負)
	SpDelta int `json:"spDelta"`
}

// HPLineReport HP の 16n / 16n-1 ライン(ADR-0150 §4)。next* は SP が現在より大きい中で最小、prev* は小さい中で最大のライン。
// HP の SP 0..32 の範囲に無ければ null。
type HPLineReport struct {
	// Current HP 実数値が属するライン(16n = HP mod 16 が 0、16n-1 = 15、none = どちらでもない)
	Current       HPLineKind   `json:"current"`
	Hp            int          `json:"hp"`
	Next16n       *HPLinePoint `json:"next16n"`
	Next16nMinus1 *HPLinePoint `json:"next16nMinus1"`
	Prev16n       *HPLinePoint `json:"prev16n"`
	Prev16nMinus1 *HPLinePoint `json:"prev16nMinus1"`
	Sp            int          `json:"sp"`
}

// Individual 計算に使う個体。SP と性格 ID から実数値を導出する
type Individual struct {
	AbilityId *string `json:"abilityId,omitempty"`

	// ItemId 持ち物。メガシンカ後の種族(isMega)は、その requiredItemId の持ち物か持ち物なし(null・省略)だけ受け付け、
	// 別の持ち物は 400 `invalid_input`(ADR-0200 §4)。
	ItemId   *string `json:"itemId,omitempty"`
	Level    *int    `json:"level,omitempty"`
	NatureId string  `json:"natureId"`

	// Ranks ランク補正(-6..+6)。HP は持たない
	Ranks *RankBlock `json:"ranks,omitempty"`

	// Sp 能力ポイント。各 0..32、合計 <= 66
	Sp StatBlock `json:"sp"`

	// SpeciesKey {図鑑番号4桁}-{フォルム3桁}
	//
	// Example: 0445-000
	SpeciesKey SpeciesKey       `json:"speciesKey"`
	Status     *StatusCondition `json:"status,omitempty"`
	TeraType   *PokeType        `json:"teraType,omitempty"`
}

// Item defines model for Item.
type Item struct {
	// Effect 持ち物の効果定義(item_effects の JSON。`getMasterExport` の `MasterItem.effect` と同じ値・同じ形。
	// issue 211・ADR-0218)。効果を持たない持ち物は**キーごと省く**(null を返さない)。
	// pokedex-svc は返す前に共通マスタ(`services/internal/master.DecodeItemEffect`)で厳格に検証し、
	// 検証を通らない効果を含む応答は返さない(503 `master_unavailable`)。
	Effect *MasterEffect `json:"effect,omitempty"`
	Id     string        `json:"id"`
	NameJa string        `json:"nameJa"`
}

// KOChance 確定数/乱数n発
type KOChance struct {
	// ChancePercent engine の生値。guaranteed が false のとき、hits 回で倒せる確率(%)を丸めずに返す
	// (ADR-0006)。guaranteed が true のとき、および hits = 0(倒せない)のときは 0。
	// **画面に出す値ではない**(確定なのに 0% と誤表示されるため)。表示には
	// displayChancePercent を使う。
	ChancePercent *float64 `json:"chancePercent,omitempty"`

	// DisplayChancePercent 画面に出す「hits 回で倒せる確率(%)」。常に表示できる値であることを保証する。
	// 小数第1位(0.1%刻み。ADR-0010 §3)。
	// - hits = 0(倒せない): 0
	// - guaranteed = true(確定 n 発): 100.0
	// - それ以外: chancePercent を 0.1% 単位に四捨五入し、[0.1, 99.9] に収める
	//   (確定・不可能と取り違えないため、0.0 と 100.0 はこの2つに予約する)
	DisplayChancePercent float64 `json:"displayChancePercent"`

	// Guaranteed 最小ダメージでも hits 回で倒せるなら true(確定n発)
	Guaranteed bool `json:"guaranteed"`

	// Hits 最大ダメージで倒すのに必要な攻撃回数(0 = 倒せない)
	Hits int `json:"hits"`
}

// MasterAbility abilities テーブルの行 + ability_effects の effect
type MasterAbility struct {
	// Effect 効果定義(item_effects / ability_effects の JSON をそのまま。ADR-0005)。null は補正なし。
	// 形は共通マスタ(`services/internal/master` の DecodeItemEffect / DecodeAbilityEffect)が受け付けるもので、
	// 受け取った側がそこで厳格に検証する(未知のキー・4096 基準の整数でない値・空のオブジェクトは不正)。
	Effect *MasterEffect `json:"effect"`
	Id     string        `json:"id"`
	NameJa string        `json:"nameJa"`
}

// MasterEffect 効果定義(item_effects / ability_effects の JSON をそのまま。ADR-0005)。null は補正なし。
// 形は共通マスタ(`services/internal/master` の DecodeItemEffect / DecodeAbilityEffect)が受け付けるもので、
// 受け取った側がそこで厳格に検証する(未知のキー・4096 基準の整数でない値・空のオブジェクトは不正)。
type MasterEffect map[string]interface{}

// MasterExport calc-svc が計算に使うマスタ一式(ADR-0204)。形は pokedex の DB の行(`services/internal/master` の
// TypeRow / TypeChartRow / SpeciesRow + SpeciesAbilityRow / MoveRow / ItemRow / AbilityRow)に対応する。
// 値の検証(ID の形式・範囲・組の整合・効果定義)は受け取った側が共通マスタの写像で行う。
type MasterExport struct {
	Abilities []MasterAbility `json:"abilities"`

	// DataVersion データの版の識別子(pokedex の data_versions に由来する)。calc-svc は記録とログに使うだけで、
	// 計算の結果には影響しない。
	DataVersion string         `json:"dataVersion"`
	Items       []MasterItem   `json:"items"`
	Moves       []MasterMove   `json:"moves"`
	Natures     []MasterNature `json:"natures"`

	// SchemaVersion この形の版。いまは 1 だけ
	SchemaVersion MasterExportSchemaVersion `json:"schemaVersion"`
	Species       []MasterSpecies           `json:"species"`

	// TypeChart タイプ相性表の行(ADR-0013)。等倍(code 2)の組は省略してよい
	TypeChart []MasterTypeChartEntry `json:"typeChart"`
	Types     []MasterType           `json:"types"`
}

// MasterExportSchemaVersion この形の版。いまは 1 だけ
type MasterExportSchemaVersion int

// MasterItem items テーブルの行 + item_effects の effect
type MasterItem struct {
	// Effect 効果定義(item_effects / ability_effects の JSON をそのまま。ADR-0005)。null は補正なし。
	// 形は共通マスタ(`services/internal/master` の DecodeItemEffect / DecodeAbilityEffect)が受け付けるもので、
	// 受け取った側がそこで厳格に検証する(未知のキー・4096 基準の整数でない値・空のオブジェクトは不正)。
	Effect *MasterEffect `json:"effect"`
	Id     string        `json:"id"`
	NameJa string        `json:"nameJa"`
}

// MasterMove moves テーブルの行(計算に使う列だけ)+ move_effects の effect(ADR-0107)
type MasterMove struct {
	Category MoveCategory `json:"category"`

	// Effect 技の追加効果(命中時のランク変化。ADR-0107)。null は追加効果なし。
	// ダメージ計算はこの値を読まない(ADR-0107 決定2)。発動するかどうかの判定も engine は行わず、
	// 「発動した場合の変化量」と「その確率」を持つだけ(ADR-0107 決定1)。
	Effect *MasterEffect `json:"effect"`
	Id     string        `json:"id"`

	// Mechanisms 技の機構(move_mechanisms。ADR-0121)。「威力・分類・タイプから通常の式で計算すると誤る」理由の
	// 分類で、1つの技が複数を持つことがある。昇順・重複なし。通常の技(変化技を含む)は空配列。
	// calc-svc は engine.Move.Mechanisms にそのまま渡す(「未対応」の印の判定に使う。ADR-0123)。
	// 値は UnsupportedMark.reason の技側13種と同じ(正は engine.AllMoveMechanisms)。ここでは
	// enum を付けない(意図的。ADR-0121 実装時の追記を参照): この内部 API は pokedex-svc → calc-svc
	// のみで使い、値の妥当性は既に `services/internal/master.MoveMechanismsOf` が検証している。
	// enum にすると oapi-codegen が別の Go 型を生成し、両サービスで `[]string` との相互変換が
	// 必要になるだけで、二重の検証にしかならない。
	Mechanisms []string `json:"mechanisms"`
	NameJa     string   `json:"nameJa"`
	Power      int      `json:"power"`
	Priority   int      `json:"priority"`
	Type       PokeType `json:"type"`
}

